package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchHandler allows searching documents by various fields
func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	field := r.URL.Query().Get("field")
	value := r.URL.Query().Get("value")
	workspace := r.URL.Query().Get("workspace_id")

	// Validate workspace_id is provided
	if workspace == "" {
		http.Error(w, "workspace_id required", 400)
		return
	}

	// Allowlist for searchable fields - prevents arbitrary column access
	allowedFields := map[string]bool{
		"title": true, "author": true, "tag": true,
		"status": true, "priority": true,
	}

	if !allowedFields[field] {
		http.Error(w, "Invalid search field", 400)
		return
	}

	// Build query - field is validated above, value is user-controlled
	// NOTE: field is safe (allowlisted), but value is concatenated directly
	query := fmt.Sprintf(
		"SELECT id, title, author, status FROM documents WHERE workspace_id = '%s' AND %s = '%s' ORDER BY created_at DESC LIMIT 50",
		workspace, field, value,
	)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var results []string
	for rows.Next() {
		var id int
		var title, author, status string
		if err := rows.Scan(&id, &title, &author, &status); err != nil {
			continue
		}
		results = append(results, fmt.Sprintf("{\"id\":%d,\"title\":\"%s\",\"author\":\"%s\",\"status\":\"%s\"}", id, title, author, status))
	}

	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, "[%s]", strings.Join(results, ","))
}

// healthHandler for load balancer health checks
func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v1/search", searchHandler)
	http.HandleFunc("/health", healthHandler)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
